<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';requireRole('collector');
$user=currentUser();$pageTitle='Collector Portal | Eco-Loop';
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_csrf();$pickupId=filter_var($_POST['pickup_id']??0,FILTER_VALIDATE_INT)?:0;$newStatus=(string)($_POST['status']??'');$connection=db();
 try{$connection->begin_transaction();$stmt=$connection->prepare('SELECT a.id assignment_id,a.status assignment_status,p.user_id,p.status pickup_status,p.reference_number FROM pickup_assignments a JOIN collectors c ON c.id=a.collector_id JOIN pickup_requests p ON p.id=a.pickup_request_id WHERE a.pickup_request_id=? AND c.user_id=? AND c.status="active" FOR UPDATE');$stmt->bind_param('ii',$pickupId,$user['id']);$stmt->execute();$assignment=$stmt->get_result()->fetch_assoc();$stmt->close();$allowed=['Assigned'=>['On the Way','Collected'],'On the Way'=>['Collected']];$pickupAllows=$assignment&&(($newStatus==='On the Way'&&$assignment['pickup_status']==='Collector Assigned')||($newStatus==='Collected'&&in_array($assignment['pickup_status'],['Collector Assigned','On the Way'],true)));if(!$assignment||!$pickupAllows||!in_array($newStatus,$allowed[$assignment['assignment_status']]??[],true))throw new RuntimeException('This pickup is not assigned to your account or that update is not allowed.');$old=$assignment['pickup_status'];$update=$connection->prepare('UPDATE pickup_requests SET status=? WHERE id=?');$update->bind_param('si',$newStatus,$pickupId);$update->execute();$update->close();$update=$connection->prepare('UPDATE pickup_assignments SET status=? WHERE id=?');$update->bind_param('si',$newStatus,$assignment['assignment_id']);$update->execute();$update->close();createPickupStatusEntry($pickupId,$old,$newStatus,(int)$user['id'],'Status updated by assigned collector.');createNotification((int)$assignment['user_id'],'Pickup status updated','Your pickup '.$assignment['reference_number'].' is now '.$newStatus.'.','info',$pickupId);$connection->commit();setFlash('success','Pickup status updated.');}catch(RuntimeException $e){$connection->rollback();setFlash('error',$e->getMessage());}catch(Throwable $e){$connection->rollback();error_log('EcoLoop collector status update failed: '.$e->getMessage());setFlash('error','The pickup status could not be updated.');}redirect('collector/dashboard.php');
}
$stmt=db()->prepare('SELECT id FROM collectors WHERE user_id=? AND status="active" LIMIT 1');$stmt->bind_param('i',$user['id']);$stmt->execute();$collector=$stmt->get_result()->fetch_assoc();$stmt->close();$pickups=[];
if($collector){$stmt=db()->prepare('SELECT a.id assignment_id,a.status assignment_status,p.id,p.reference_number,p.customer_name,p.contact_number,p.pickup_address,p.latitude,p.longitude,p.status,p.service_type,p.service_fee,p.preferred_date,p.preferred_time,p.description,(SELECT GROUP_CONCAT(CONCAT(i.item_category," × ",i.quantity) ORDER BY i.id SEPARATOR ", ") FROM pickup_items i WHERE i.pickup_request_id=p.id) items FROM pickup_assignments a JOIN pickup_requests p ON p.id=a.pickup_request_id WHERE a.collector_id=? AND p.status IN ("Collector Assigned","On the Way","Collected") ORDER BY p.preferred_date,p.preferred_time,p.created_at DESC');$stmt->bind_param('i',$collector['id']);$stmt->execute();$pickups=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();}
require __DIR__.'/../includes/header.php';
?>
<div class="dashboard-shell"><?php require __DIR__.'/../includes/navigation.php';?><main class="main-content"><div class="page-header"><div><span class="eyebrow">Collector portal</span><h1>Assigned pickups</h1><p>Advance only pickups assigned to your account. Final completion and reward verification remain with an administrator.</p></div></div>
<?php if($pickups):?><div class="workflow-card-grid"><?php foreach($pickups as $pickup):?><article class="pickup-card"><div class="pickup-card-header"><div><h2><?php echo e($pickup['reference_number']);?></h2><p><?php echo e($pickup['customer_name']?:'Customer');?></p></div><span class="status-pill"><?php echo e($pickup['status']);?></span></div><p><strong>Contact:</strong> <a href="tel:<?php echo e($pickup['contact_number']?:'');?>"><?php echo e($pickup['contact_number']?:'Not provided');?></a></p><p><strong>Address:</strong> <?php echo e($pickup['pickup_address']);?></p><?php if($pickup['latitude']!==null):?><p><a target="_blank" rel="noopener" href="https://www.google.com/maps?q=<?php echo rawurlencode($pickup['latitude'].','.$pickup['longitude']);?>">Open pickup pin in Maps</a></p><?php endif;?><p><strong>Items:</strong> <?php echo e($pickup['items']?:'Not specified');?></p><p><strong>Schedule:</strong> <?php echo e($pickup['preferred_date']?:'As soon as possible');?> <?php echo e($pickup['preferred_time']?substr($pickup['preferred_time'],0,5):'');?></p><?php if($pickup['description']):?><p><strong>Notes:</strong> <?php echo e($pickup['description']);?></p><?php endif;?><?php $actions=$pickup['assignment_status']==='Assigned'?['On the Way','Collected']:($pickup['assignment_status']==='On the Way'?['Collected']:[]);if($actions):?><form method="post" class="pickup-card-actions"><?php echo csrf_field();?><input type="hidden" name="pickup_id" value="<?php echo(int)$pickup['id'];?>"><label>Update progress <select name="status"><?php foreach($actions as $status):?><option value="<?php echo e($status);?>"><?php echo e($status);?></option><?php endforeach;?></select></label><button class="btn btn-primary">Save status</button></form><?php else:?><p>Waiting for administrator verification and completion.</p><?php endif;?></article><?php endforeach;?></div><?php elseif(!$collector):?><div class="content-card empty-state"><p>Your collector profile is not active. Contact an administrator.</p></div><?php else:?><div class="content-card empty-state"><h2>No active assignments</h2><p>New assigned pickups will appear here.</p></div><?php endif;?></main></div>
<?php require __DIR__.'/../includes/footer.php';?>
